const rows = $input.all();
const unused = rows.filter(item => {
  const val = String(item.json.used || '').trim().toUpperCase();
  return val !== 'TRUE';
});
if (!unused.length) throw new Error('No unused testimonials in sheet. Mark some rows used=FALSE or add more rows.');
const selected = unused[Math.floor(Math.random() * unused.length)];
return [{ json: selected.json }];

const geminiResp = $json;
const caption = geminiResp.candidates?.[0]?.content?.parts?.[0]?.text?.trim() || '';
if (!caption) throw new Error('Gemini returned no caption text.');
const firstName = ($json.borrower_name || '').split(' ')[0];
const shortQuote = ($json.testimonial_text || '').substring(0, 120);
const imagePrompt = `Professional social media quote card. Dark background (#1a1a1a). Gold accent bar at top (#c9a84c). White serif text in center: "${shortQuote}" — ${firstName}. Bottom text in small gold font: Adam Styer | Mortgage Solutions LP. Clean, minimal, premium mortgage brand aesthetic. No people, no faces. Portrait/square format.`;
return [{ json: { ...$json, instagram_caption: caption, image_prompt: imagePrompt } }];

const predictions = $json.predictions;
if (!predictions || !predictions.length) throw new Error('Gemini imagen returned no predictions.');
const base64Image = predictions[0].bytesBase64Encoded;
if (!base64Image) throw new Error('No base64 image data in Gemini response.');
const imageBuffer = Buffer.from(base64Image, 'base64');
const supabaseUrl = 'https://uuqedsvjlkeszrbwzizl.supabase.co';
const supabaseKey = 'YOUR_SUPABASE_SERVICE_ROLE_KEY';
const bucket = 'social-assets';
const fileName = `testimonial-${Date.now()}.jpg`;
const uploadResp = await fetch(`${supabaseUrl}/storage/v1/object/${bucket}/${fileName}`, {
  method: 'POST',
  headers: {
    'Authorization': `Bearer ${supabaseKey}`,
    'Content-Type': 'image/jpeg'
  },
  body: imageBuffer
});
if (!uploadResp.ok) {
  const err = await uploadResp.text();
  throw new Error(`Supabase Storage upload failed: ${err}`);
}
const publicUrl = `${supabaseUrl}/storage/v1/object/public/${bucket}/${fileName}`;
const prevData = $('Random Select Unused Testimonial').first().json;
return [{ json: { ...prevData, image_public_url: publicUrl, instagram_caption: $('Extract Caption + Build Image Prompt').first().json.instagram_caption } }];
